/** Checkpoint 1 band/verdict reader tests — node --test, fixtures only (no Python). */

// tests/fixtures/real-verdict.jsonl is hand-derived from harness/measure.py
// (class Band's formulas, screen_verdict, promote_bar — see the comments in
// app/static/band.js for the exact lines) to produce the *real* emitted band
// shape (an asdict(Band) object), unlike tests/fixtures/fake-events.jsonl's
// verdicts, which carry fake_run.py's legacy [lo, hi] shape. It is NOT
// generated by running the harness and must never be regenerated.

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { readBand, verdictReading, verdictAnnotation, SCREEN_ADVANCE_SD, BAND_FIELDS } from "./band.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REAL_VERDICT_FIXTURE = join(
  __dirname,
  "..",
  "..",
  "tests",
  "fixtures",
  "real-verdict.jsonl",
);
const FAKE_EVENTS_FIXTURE = join(
  __dirname,
  "..",
  "..",
  "tests",
  "fixtures",
  "fake-events.jsonl",
);
const MEASURE_PY = join(__dirname, "..", "..", "harness", "measure.py");

function loadJsonl(path) {
  const text = readFileSync(path, "utf8");
  return text
    .split("\n")
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line));
}

function loadRealVerdicts() {
  return loadJsonl(REAL_VERDICT_FIXTURE);
}

describe("band — readBand shapes", () => {
  it("test_readBand_measure_shape", () => {
    const raw = { sigma_screen: 0.02, bar: 0.01, source: "fixed_pair" };
    const result = readBand(raw);
    assert.equal(result.shape, "measure");
    assert.equal(result.fields, raw);
  });

  it("test_readBand_legacy_shape", () => {
    const result = readBand([0.5, 0.52]);
    assert.equal(result.shape, "legacy");
    assert.deepEqual(result.fields, { lo: 0.5, hi: 0.52 });
  });

  it("test_readBand_none_shape", () => {
    for (const raw of [null, undefined, [], [0.5], [0.5, 0.52, 0.6], ["a", "b"], "band", 5]) {
      const result = readBand(raw);
      assert.equal(result.shape, "none", `expected none for ${JSON.stringify(raw)}`);
      assert.equal(result.fields, null);
    }
  });

  it("test_readBand_never_throws", () => {
    for (const raw of [null, undefined, {}, [], NaN, Symbol("x")]) {
      assert.doesNotThrow(() => readBand(raw));
    }
  });
});

// harness/measure.py:417 (`rung=rung,`) and :433 (`"rung": rung,`) are how
// the harness itself tags a verdict with the comparison that produced it —
// that's why real-verdict.jsonl's verdicts carry a "rung" key: it's not
// inferable from "state" alone (see test_replicating_uses_the_screen_threshold
// and test_rejected_at_replicate_uses_bar below for why state guessing fails).
describe("band — verdictReading against the real fixture", () => {
  it("test_screening_verdict_threshold_is_sd_delta_screen_derived", () => {
    const verdicts = loadRealVerdicts();
    const screening = verdicts.find((e) => e.type === "verdict" && e.state === "inconclusive");
    assert.equal(screening.rung, "screen");
    const reading = verdictReading(screening);
    assert.equal(reading.shape, "measure");
    assert.equal(reading.valueKind, "delta");
    assert.equal(reading.value, screening.delta_mean);
    // harness/measure.py:194: delta >= SCREEN_ADVANCE_SD * band.sd_delta_screen
    assert.equal(reading.threshold, SCREEN_ADVANCE_SD * screening.band.sd_delta_screen);
    assert.equal(reading.thresholdLabel, "sd_delta_screen");
    assert.ok(reading.value < reading.threshold);
    assert.equal(reading.side, "below");
    assert.equal(reading.rung, "screen");
  });

  it("test_promoted_verdict_threshold_is_bar", () => {
    const verdicts = loadRealVerdicts();
    const promoted = verdicts.find((e) => e.type === "verdict" && e.state === "promoted");
    assert.equal(promoted.rung, "replicate");
    const reading = verdictReading(promoted);
    assert.equal(reading.shape, "measure");
    assert.equal(reading.valueKind, "delta");
    assert.equal(reading.value, promoted.delta_mean);
    // harness/measure.py:199-200: promote_bar(band) returns band.bar's value
    assert.equal(reading.threshold, promoted.band.bar);
    assert.equal(reading.thresholdLabel, "bar");
    assert.ok(reading.value > reading.threshold);
    assert.equal(reading.side, "above");
    assert.equal(reading.rung, "replicate");
  });

  it("test_replicating_uses_the_screen_threshold", () => {
    // The old state -> split mapping (deleted from band.js) treated
    // "replicating" as a replication-rung state, but harness/measure.py:369
    // (`state = decision  # rejected | replicating | inconclusive`) shows
    // "replicating" is one of screen_verdict's own outcomes — it is what the
    // *screen* rung produces when it passes, before any replicate rung has
    // run. Rung, not state, says which comparison was made.
    const verdict = {
      type: "verdict",
      state: "replicating",
      rung: "screen",
      metric: "cvr_auc",
      delta_mean: 0.02,
      band: {
        sigma_screen: 0.02,
        sigma_full: 0.012,
        sigma_pair: 0.01,
        ratio: 0.6,
        rho: 0.8,
        sd_delta_screen: 0.012649,
        sd_delta_full: 0.007589,
        bar: 0.01,
        source: "fixed_pair",
        n_replicated: 0,
      },
    };
    const reading = verdictReading(verdict);
    assert.equal(reading.thresholdLabel, "sd_delta_screen");
    assert.equal(reading.threshold, SCREEN_ADVANCE_SD * verdict.band.sd_delta_screen);
  });

  it("test_rejected_at_replicate_uses_bar", () => {
    // harness/measure.py:406 and :409 both assign state = "rejected" inside
    // the rung === "replicate" branch (fail_sign, fail_mean) — "rejected" is
    // not exclusively a screen-rung outcome either; the old mapping treated
    // it as one.
    const verdict = {
      type: "verdict",
      state: "rejected",
      rung: "replicate",
      metric: "cvr_auc",
      delta_mean: 0.002,
      band: {
        sigma_screen: 0.02,
        sigma_full: 0.012,
        sigma_pair: 0.01,
        ratio: 0.6,
        rho: 0.8,
        sd_delta_screen: 0.012649,
        sd_delta_full: 0.007589,
        bar: 0.01,
        source: "fixed_pair",
        n_replicated: 1,
      },
    };
    const reading = verdictReading(verdict);
    assert.equal(reading.thresholdLabel, "bar");
    assert.equal(reading.threshold, verdict.band.bar);
  });

  it("test_dict_band_without_rung_has_no_threshold", () => {
    // fake_run.py emits no "rung" field at all today. A dict-shaped band
    // with no rung is a real, honest case: we don't know which comparison
    // the harness made, so we must not guess from state.
    const verdict = {
      type: "verdict",
      state: "promoted",
      metric: "cvr_auc",
      delta_mean: 0.02,
      band: {
        sigma_screen: 0.02,
        sigma_full: 0.012,
        sigma_pair: 0.01,
        ratio: 0.6,
        rho: 0.8,
        sd_delta_screen: 0.012649,
        sd_delta_full: 0.007589,
        bar: 0.01,
        source: "fixed_pair",
        n_replicated: 1,
      },
      // no "rung" key at all
    };
    const reading = verdictReading(verdict);
    assert.equal(reading.shape, "measure");
    assert.equal(reading.threshold, null);
    assert.equal(reading.thresholdLabel, null);
    assert.equal(reading.rung, null);
    assert.equal(reading.value, 0.02);
  });
});

describe("band — verdictReading edge shapes", () => {
  it("test_legacy_band_verdict_has_null_threshold", () => {
    // fake-events.jsonl (committed, not regenerated) still carries
    // fake_run.py's legacy [lo, hi] band shape on every verdict.
    const events = loadJsonl(FAKE_EVENTS_FIXTURE);
    const legacyVerdict = events.find((e) => e.type === "verdict" && Array.isArray(e.band));
    assert.ok(legacyVerdict, "expected at least one verdict with an array band in fake-events.jsonl");
    const reading = verdictReading(legacyVerdict);
    assert.equal(reading.shape, "legacy");
    assert.equal(reading.threshold, null);
    assert.equal(reading.thresholdLabel, null);
    assert.equal(reading.side, null);
  });

  it("test_band_absent_verdict_still_reports_value", () => {
    const verdict = {
      type: "verdict",
      state: "promoted",
      metric: "cvr_auc",
      delta_mean: 0.02,
      scores: [0.53],
      // no "band" key at all
    };
    const reading = verdictReading(verdict);
    assert.equal(reading.shape, "none");
    assert.equal(reading.threshold, null);
    assert.equal(reading.side, null);
    assert.equal(reading.valueKind, "delta");
    assert.equal(reading.value, 0.02); // the number is never suppressed
  });
});

describe("band — verdictAnnotation", () => {
  it("test_annotation_reports_the_harness_comparison", () => {
    const verdicts = loadRealVerdicts();
    const promoted = verdicts.find((e) => e.type === "verdict" && e.state === "promoted");
    const reading = verdictReading(promoted);
    const { text, reason } = verdictAnnotation(promoted);
    assert.equal(reason, null);
    assert.ok(text.includes(String(reading.value)), `expected text to contain the delta ${reading.value}: ${text}`);
    assert.ok(text.includes("≥"), `expected text to contain the ≥ symbol: ${text}`);
    assert.ok(
      text.includes(reading.thresholdLabel),
      `expected text to contain thresholdLabel ${reading.thresholdLabel}: ${text}`,
    );
    assert.ok(
      text.includes(String(reading.threshold)),
      `expected text to contain the threshold ${reading.threshold}: ${text}`,
    );
  });

  it("test_annotation_on_legacy_band_gives_a_reason_not_a_threshold", () => {
    const events = loadJsonl(FAKE_EVENTS_FIXTURE);
    const legacyVerdict = events.find((e) => e.type === "verdict" && Array.isArray(e.band));
    assert.ok(legacyVerdict, "expected at least one verdict with an array band in fake-events.jsonl");
    const { text, reason } = verdictAnnotation(legacyVerdict);
    assert.equal(text, null);
    assert.match(reason, /noise bar/, `expected the reason to name the noise bar: ${reason}`);
    assert.doesNotMatch(reason, /\bband\b/i, `reason still says "band": ${reason}`);
    assert.doesNotMatch(reason, /\bharness\b/i, `reason still says "harness": ${reason}`);
    assert.doesNotMatch(reason, /fake_run/, `reason still names fake_run.py: ${reason}`);
    // lo/hi are never themselves called a threshold — rule 3 of the band
    // contract (Handoff_app.md): "`lo`/`hi` are not something screen_verdict
    // or promote_bar compared against."
    assert.doesNotMatch(
      reason,
      /lo\/hi\s+threshold|threshold\s+of\s+lo\/hi|band\s+threshold/i,
      `reason must not describe lo/hi itself as a threshold: ${reason}`,
    );
  });

  it("test_annotation_without_rung_gives_a_reason", () => {
    const verdict = {
      type: "verdict",
      state: "promoted",
      metric: "cvr_auc",
      delta_mean: 0.02,
      band: {
        sigma_screen: 0.02,
        sigma_full: 0.012,
        sigma_pair: 0.01,
        ratio: 0.6,
        rho: 0.8,
        sd_delta_screen: 0.012649,
        sd_delta_full: 0.007589,
        bar: 0.01,
        source: "fixed_pair",
        n_replicated: 1,
      },
      // no "rung" key at all
    };
    const { text, reason } = verdictAnnotation(verdict);
    assert.equal(text, null);
    assert.match(reason, /test kind/i, `expected the reason to name the missing test kind: ${reason}`);
    assert.doesNotMatch(reason, /\bharness\b/i, `reason still says "harness": ${reason}`);
  });

  it("test_annotation_without_band_gives_a_reason", () => {
    const verdict = {
      type: "verdict",
      state: "promoted",
      metric: "cvr_auc",
      delta_mean: 0.02,
      scores: [0.53],
      // no "band" key at all
    };
    const { text, reason } = verdictAnnotation(verdict);
    assert.equal(text, null);
    assert.match(reason, /no noise bar/i, `expected the reason to say no noise bar was reported: ${reason}`);
    assert.doesNotMatch(reason, /\bband\b/i, `reason still says "band": ${reason}`);
  });
});

describe("band — sync with harness/measure.py", () => {
  it("test_band_fields_match_python", () => {
    const src = readFileSync(MEASURE_PY, "utf8");
    // Same comment-stripping approach as reducer.test.js's extractTuple:
    // a trailing "#..." comment could otherwise smuggle stray tokens in.
    const srcNoComments = src
      .split("\n")
      .map((line) => line.replace(/#.*$/, ""))
      .join("\n");
    const m = srcNoComments.match(/class Band:\n([\s\S]*?)\n\s*\n/);
    assert.ok(m, "could not find class Band in harness/measure.py");
    const body = m[1];
    const fieldRe = /^\s+(\w+)\s*:/gm;
    const fields = [];
    let fm;
    while ((fm = fieldRe.exec(body)) !== null) {
      fields.push(fm[1]);
    }
    assert.deepEqual(fields, BAND_FIELDS);
  });

  it("test_screen_advance_sd_matches_python", () => {
    const src = readFileSync(MEASURE_PY, "utf8");
    const srcNoComments = src
      .split("\n")
      .map((line) => line.replace(/#.*$/, ""))
      .join("\n");
    const m = srcNoComments.match(/SCREEN_ADVANCE_SD\s*=\s*([0-9.]+)/);
    assert.ok(m, "could not find SCREEN_ADVANCE_SD in harness/measure.py");
    assert.equal(Number(m[1]), SCREEN_ADVANCE_SD);
  });
});

describe("band — real fixture is internally consistent with harness/measure.py", () => {
  it("test_real_fixture_band_keys_match_python", () => {
    const verdicts = loadRealVerdicts();
    for (const ev of verdicts) {
      assert.ok(ev.band && typeof ev.band === "object", `expected an object band on seq ${ev.seq}`);
      assert.deepEqual(
        Object.keys(ev.band).sort(),
        [...BAND_FIELDS].sort(),
        `band keys on seq ${ev.seq} must match BAND_FIELDS`,
      );
    }
  });

  it("test_real_fixture_bar_is_internally_consistent", () => {
    const src = readFileSync(MEASURE_PY, "utf8");
    const srcNoComments = src
      .split("\n")
      .map((line) => line.replace(/#.*$/, ""))
      .join("\n");
    // Step 5 made the floor calibratable: harness/measure.py now binds
    // PROMOTE_FLOOR to a name (_PROMOTE_FLOOR_DEFAULT = 0.010) and rebinds it
    // to `2.0 * SIGMA` inside _apply_calibration. Scraping /PROMOTE_FLOOR\s*=/
    // therefore reads the calibration expression's leading 2.0, not a floor.
    // The fake stream runs an uncalibrated protocol, so the default is the
    // value its bars were computed with.
    const floorM = srcNoComments.match(/_PROMOTE_FLOOR_DEFAULT\s*=\s*([0-9.]+)/);
    assert.ok(floorM, "could not find _PROMOTE_FLOOR_DEFAULT in harness/measure.py");
    // harness/measure.py:23: PROMOTE_Z_OVER_SQRT_K = 0.95
    const zM = srcNoComments.match(/PROMOTE_Z_OVER_SQRT_K\s*=\s*([0-9.]+)/);
    assert.ok(zM, "could not find PROMOTE_Z_OVER_SQRT_K in harness/measure.py");
    const PROMOTE_FLOOR = Number(floorM[1]);
    const PROMOTE_Z_OVER_SQRT_K = Number(zM[1]);

    const verdicts = loadRealVerdicts();
    for (const ev of verdicts) {
      const band = ev.band;
      // harness/measure.py:116-117 (_bar_from):
      //   def _bar_from(sd_delta_full: float) -> float:
      //       return max(PROMOTE_FLOOR, PROMOTE_Z_OVER_SQRT_K * float(sd_delta_full))
      const expectedBar = Math.max(PROMOTE_FLOOR, PROMOTE_Z_OVER_SQRT_K * band.sd_delta_full);
      assert.ok(
        Math.abs(band.bar - expectedBar) < 1e-9,
        `seq ${ev.seq}: bar=${band.bar} does not match max(PROMOTE_FLOOR, PROMOTE_Z_OVER_SQRT_K * sd_delta_full)=${expectedBar} — fix the fixture, not this test`,
      );
    }
  });

  it("test_sd_delta_screen_is_internally_consistent", () => {
    const verdicts = loadRealVerdicts();
    for (const ev of verdicts) {
      const band = ev.band;
      // harness/measure.py:112-113 (_sd_delta):
      //   def _sd_delta(sigma: float, rho: float) -> float:
      //       return float(sigma) * math.sqrt(2.0 * (1.0 - float(rho)))
      const expected = band.sigma_screen * Math.sqrt(2.0 * (1.0 - band.rho));
      assert.ok(
        Math.abs(band.sd_delta_screen - expected) < 1e-5,
        `seq ${ev.seq}: sd_delta_screen=${band.sd_delta_screen} does not match sigma_screen * sqrt(2 * (1 - rho))=${expected} — fix the fixture, not this test`,
      );
    }
  });
});
